import fs from "node:fs";
import os from "node:os";
import path from "node:path";
/**
 * Scope at which a Claude Code plugin can be installed.
 * Mirrors the values stored in `~/.claude/plugins/installed_plugins.json`.
 */
export const INSTALL_SCOPES = ["user", "project", "local", "managed"];
export function isInstallScope(value) {
    return (typeof value === "string" &&
        INSTALL_SCOPES.includes(value));
}
/**
 * Scopes to hand to `claude plugin update`. `claude` defaults to user scope and
 * fails outright when the plugin lives at another scope, so an empty detection
 * result keeps that historical default while a detected set updates every scope
 * the plugin is actually installed at.
 */
export function pluginUpdateScopes(scopes) {
    return scopes.length > 0 ? [...scopes] : ["user"];
}
/**
 * Whether an install recorded against `projectPath` governs the project at
 * `projectDir`. Project- and local-scoped installs belong to one project root
 * and record it; `claude plugin update --scope project` run anywhere else fails
 * outright, so another project's install must not be reported here. Installs
 * with no recorded project (user and managed scope) apply everywhere.
 *
 * Shared with bitfab-cli, which resolves the same question from
 * `claude plugin list --json` instead of installed_plugins.json.
 */
export function installScopeAppliesToProject(projectPath, projectDir) {
    if (typeof projectPath !== "string" || projectPath.trim() === "") {
        return true;
    }
    const project = canonicalPath(projectPath);
    const current = canonicalPath(projectDir);
    return current === project || current.startsWith(`${project}${path.sep}`);
}
/**
 * Symlinks are resolved before comparing: `claude` records the path it was
 * given, so a project reached through a symlink (macOS `/tmp` -> `/private/tmp`,
 * a linked home or worktree root) would otherwise read as a different project
 * and lose its install scope. Falls back to a plain resolve when the path no
 * longer exists.
 */
function canonicalPath(target) {
    try {
        return fs.realpathSync(path.resolve(target));
    }
    catch {
        return path.resolve(target);
    }
}
/**
 * Read `~/.claude/plugins/installed_plugins.json` and return the distinct
 * scopes the given `<plugin>@<marketplace>` key is installed at for the project
 * at `projectDir`. Returns an empty array when the file is missing, malformed,
 * or the key is absent for this project - callers should treat that as "scope
 * detection isn't available".
 *
 * `homeDir` and `projectDir` override `os.homedir()` / `process.cwd()`.
 */
export function detectClaudeInstallScopes(pluginKey, homeDir = os.homedir(), projectDir = process.cwd()) {
    try {
        const installedPath = path.join(homeDir, ".claude", "plugins", "installed_plugins.json");
        const content = fs.readFileSync(installedPath, "utf-8");
        const data = JSON.parse(content);
        const entries = data.plugins?.[pluginKey] ?? [];
        const scopes = new Set();
        for (const entry of entries) {
            if (entry.scope &&
                installScopeAppliesToProject(entry.projectPath, projectDir)) {
                scopes.add(entry.scope);
            }
        }
        return Array.from(scopes);
    }
    catch {
        return [];
    }
}
